#!/usr/bin/env python3
"""Build the security report for a MijnBureau release.

The report is generated from the *rendered* manifests, not from
``helmfile/environments/default/container.yaml.gotmpl``: charts add sidecars,
init containers and Job images, and an image may be used by several
environments.

For every image the script records:

* the digest the tag currently resolves to (per target platform),
* whether the image carries a cosign signature and who signed it,
* a CycloneDX and an SPDX SBOM generated by Syft from that digest,
* a Trivy vulnerability report for the CycloneDX SBOM.

Signature verification is report-only: unsigned or unverifiable images never
fail the run. Missing SBOMs or unreadable images are recorded as errors and do
not abort the release either, so one broken upstream never blocks publishing.

Usage:
    MIJNBUREAU_MASTER_PASSWORD=test python3 scripts/release_report.py \
        --release-tag v1.2.3 --output-dir output/release

Afterwards ``output/release/security`` contains ``containers.json``,
``containers.md``, ``images.lock.yaml``, ``sbom-index.json``,
``signatures.json``, ``cve.json`` and ``SHA256SUMS``.
"""

import argparse
import concurrent.futures
import datetime
import hashlib
import json
import os
import re
import shutil
import subprocess
import sys
import threading
import time

try:
    import yaml
except ImportError:  # pragma: no cover - dependency is installed by CI
    sys.exit("PyYAML is required: pip install pyyaml")


WORKLOAD_KINDS = {
    "Deployment",
    "StatefulSet",
    "DaemonSet",
    "Job",
    "CronJob",
    "Pod",
    "ReplicaSet",
    "ReplicationController",
}

# Tags that move without any change in Git. These need a digest to be
# reproducible; the report marks them so consumers can spot them.
MUTABLE_TAGS = {"main", "master", "latest", "stable", "edge", "nightly", "dev", "develop"}

# A registry that has no signature for the digest at all.
UNSIGNED_MARKERS = (
    "no signatures found",
    "no signature found",
    "signature not found",
    "manifest_unknown",
    "entity was not found",
    "404 not found",
)

# Signatures exist, but not in a form this report can validate: signed with an
# unknown key, or with a key where a certificate was expected (and vice versa).
UNVERIFIABLE_MARKERS = (
    "no matching signatures",
    "no matching attestations",
    "expected key signature, not certificate",
    "expected certificate",
)

_print_lock = threading.Lock()


def log(message):
    with _print_lock:
        print(message, flush=True)


def run(command, check=True, capture=True, timeout=1800, env=None):
    """Run a command and return its completed process."""
    result = subprocess.run(
        command,
        check=False,
        capture_output=capture,
        text=True,
        timeout=timeout,
        env=env,
    )
    if check and result.returncode != 0:
        raise RuntimeError(
            f"command failed ({result.returncode}): {' '.join(command)}\n"
            f"{(result.stderr or result.stdout or '').strip()[:2000]}"
        )
    return result


def tool_versions(tools):
    """Return the version string of each tool, for the report header."""
    versions = {}
    for tool, flags in tools.items():
        if not shutil.which(tool):
            versions[tool] = "missing"
            continue
        try:
            out = run([tool, *flags], check=False).stdout or ""
            versions[tool] = out.strip().splitlines()[0] if out.strip() else "unknown"
        except (OSError, subprocess.TimeoutExpired):
            versions[tool] = "unknown"
    return versions


def render_manifests(environments, output_dir, helmfile_bin="helmfile"):
    """Render every environment into ``output_dir/<environment>``."""
    rendered = {}
    for environment in environments:
        target = os.path.join(output_dir, environment)
        if os.path.isdir(target):
            shutil.rmtree(target)
        os.makedirs(target, exist_ok=True)
        log(f"[render] helmfile -e {environment} template -> {target}")
        command = [helmfile_bin, "-e", environment, "template", f"--output-dir={target}"]
        result = run(command, check=False, capture=True)
        if result.returncode != 0:
            raise RuntimeError(
                f"helmfile -e {environment} template failed\n{(result.stderr or result.stdout)[-4000:]}"
            )
        rendered[environment] = target
    return rendered


def iter_yaml_documents(root):
    """Yield every YAML document found below ``root``."""
    for directory, _dirs, files in os.walk(root):
        for name in sorted(files):
            if not name.endswith((".yaml", ".yml")):
                continue
            path = os.path.join(directory, name)
            try:
                with open(path, encoding="utf-8") as handle:
                    for document in yaml.safe_load_all(handle):
                        if isinstance(document, dict):
                            yield document
            except (yaml.YAMLError, UnicodeDecodeError) as error:
                log(f"[warn] skipping unparsable manifest {path}: {error}")


def pod_spec(manifest):
    """Return the pod spec of a workload manifest, if it has one."""
    kind = manifest.get("kind")
    spec = manifest.get("spec") or {}
    if kind == "Pod":
        return spec
    if kind == "CronJob":
        return (
            (spec.get("jobTemplate") or {})
            .get("spec", {})
            .get("template", {})
            .get("spec", {})
        )
    return (spec.get("template") or {}).get("spec", {})


def workload_name(manifest):
    metadata = manifest.get("metadata") or {}
    labels = metadata.get("labels") or {}
    for label in ("app.kubernetes.io/name", "app", "k8s-app", "component"):
        if labels.get(label):
            return str(labels[label])
    return str(metadata.get("name") or "unknown")


def collect_images(rendered):
    """Map image reference -> usages across environments.

    Returns ``{image: {"environments": set(), "usages": [...]}}``.
    """
    images = {}
    for environment, root in rendered.items():
        for manifest in iter_yaml_documents(root):
            kind = manifest.get("kind")
            if kind not in WORKLOAD_KINDS:
                continue
            metadata = manifest.get("metadata") or {}
            spec = pod_spec(manifest) or {}
            for field in ("initContainers", "containers"):
                for container in spec.get(field) or []:
                    image = (container or {}).get("image")
                    if not image:
                        continue
                    image = image.strip().strip('"')
                    entry = images.setdefault(
                        image, {"environments": set(), "usages": []}
                    )
                    entry["environments"].add(environment)
                    entry["usages"].append(
                        {
                            "environment": environment,
                            "namespace": metadata.get("namespace") or "",
                            "kind": kind,
                            "workload": metadata.get("name") or "",
                            "component": workload_name(manifest),
                            "container": container.get("name") or "",
                            "init_container": field == "initContainers",
                            "imagePullPolicy": container.get("imagePullPolicy") or "",
                        }
                    )
    return images


def split_image(image):
    """Split an image reference into name, tag and digest."""
    digest = None
    if "@" in image:
        image, digest = image.split("@", 1)
    tag = None
    last_slash = image.rfind("/")
    last_colon = image.rfind(":")
    if last_colon > last_slash:
        image, tag = image[:last_colon], image[last_colon + 1 :]
    return image, tag, digest


def parse_platform(value):
    parts = value.split("/")
    platform = {"os": parts[0], "architecture": parts[1] if len(parts) > 1 else "amd64"}
    if len(parts) > 2:
        platform["variant"] = parts[2]
    return platform


def resolve_digest(image, platform):
    """Resolve an image tag to its index digest and platform manifest digest."""
    result = run(["skopeo", "inspect", "--raw", f"docker://{image}"], timeout=300)
    raw = result.stdout.encode()
    document = json.loads(result.stdout)
    index_digest = "sha256:" + hashlib.sha256(raw).hexdigest()

    manifests = document.get("manifests")
    if not manifests:
        return {
            "digest": index_digest,
            "platform_digest": index_digest,
            "media_type": document.get("mediaType", ""),
            "index": False,
        }

    match = None
    for entry in manifests:
        entry_platform = entry.get("platform") or {}
        if entry_platform.get("os") != platform["os"]:
            continue
        if entry_platform.get("architecture") != platform["architecture"]:
            continue
        if platform.get("variant") and entry_platform.get("variant") != platform["variant"]:
            continue
        match = entry
        break

    return {
        "digest": index_digest,
        "platform_digest": match.get("digest") if match else index_digest,
        "media_type": document.get("mediaType", ""),
        "index": True,
        "platform_found": match is not None,
    }


def classify_cosign_failure(stderr):
    lowered = (stderr or "").lower()
    if any(marker in lowered for marker in UNSIGNED_MARKERS):
        return "unsigned"
    if any(marker in lowered for marker in UNVERIFIABLE_MARKERS):
        return "unverifiable"
    return "error"


def parse_cosign_identity(stdout):
    """Extract issuer/subject from ``cosign verify`` JSON output."""
    try:
        payload = json.loads(stdout)
    except (json.JSONDecodeError, TypeError):
        return None, None
    if isinstance(payload, dict):
        payload = [payload]
    for entry in payload:
        optional = (entry or {}).get("optional") or {}
        issuer = optional.get("Issuer")
        subject = optional.get("Subject")
        if issuer or subject:
            return issuer, subject
    return None, None


def verify_signature(image, digest, public_key, checked_at):
    """Report-only cosign verification (keyless first, then this repo's key)."""
    signature = {
        "status": "unsigned",
        "method": "none",
        "identity": None,
        "issuer": None,
        "checked_at": checked_at,
        "detail": "",
    }
    if not digest:
        signature.update(status="error", detail="no digest to verify")
        return signature

    reference = f"{image}@{digest}"
    keyless = run(
        [
            "cosign",
            "verify",
            "--certificate-oidc-issuer-regexp",
            ".*",
            "--certificate-identity-regexp",
            ".*",
            reference,
        ],
        check=False,
        timeout=300,
    )
    if keyless.returncode == 0:
        issuer, subject = parse_cosign_identity(keyless.stdout)
        signature.update(
            status="verified",
            method="keyless",
            identity=subject,
            issuer=issuer,
        )
        return signature

    keyed_status = None
    if public_key and os.path.exists(public_key):
        keyed = run(
            ["cosign", "verify", "--key", public_key, reference],
            check=False,
            timeout=300,
        )
        if keyed.returncode == 0:
            signature.update(status="verified", method="key", identity="cosign.pub")
            return signature
        keyed_status = classify_cosign_failure(keyed.stderr)

    keyless_status = classify_cosign_failure(keyless.stderr)
    if "unsigned" in (keyless_status, keyed_status):
        signature.update(status="unsigned", detail="no cosign signature found")
    elif "unverifiable" in (keyless_status, keyed_status):
        signature.update(
            status="unverifiable",
            detail="signature found, but not by a keyless certificate or cosign.pub",
        )
    else:
        detail = (keyless.stderr or "").strip().splitlines()
        signature.update(
            status="error",
            detail=(detail[-1] if detail else "signature verification failed")[:300],
        )
    return signature


def slugify(value, fallback="image"):
    slug = re.sub(r"[^a-z0-9]+", "-", value.lower()).strip("-")
    return slug or fallback


def generate_sboms(image, digest, tag, sbom_dir, formats):
    """Generate one SBOM per requested format with Syft."""
    reference = f"{image}@{digest}" if digest else image
    repository = image.split("/")[-1] if "/" in image else image
    base = f"{slugify(repository)}-{slugify(tag or 'pinned')}"
    if digest:
        base = f"{base}-{digest[-8:]}"
    produced = {}
    for sbom_format, suffix in formats.items():
        target = os.path.join(sbom_dir, f"{base}.{suffix}")
        command = ["syft", reference, "-q", "-o", f"{sbom_format}={target}"]
        # One retry covers transient registry errors without hiding real ones.
        for attempt in range(2):
            result = run(command, check=False, timeout=3600)
            if result.returncode == 0 and os.path.exists(target):
                break
            if attempt == 0:
                time.sleep(3)
        if result.returncode != 0 or not os.path.exists(target):
            produced[sbom_format] = {
                "file": None,
                "error": (result.stderr or result.stdout or "syft failed").strip()[-400:],
            }
            continue
        produced[sbom_format] = {
            "file": os.path.relpath(target, os.path.dirname(sbom_dir)),
            "sha256": file_sha256(target),
            "bytes": os.path.getsize(target),
        }
    return produced


def trivy_scan(sbom_path, cache_dir):
    """Scan a CycloneDX SBOM with Trivy and return the parsed JSON."""
    result = run(
        [
            "trivy",
            "sbom",
            "--scanners",
            "vuln",
            "--format",
            "json",
            "--quiet",
            "--cache-dir",
            cache_dir,
            sbom_path,
        ],
        check=False,
        timeout=3600,
    )
    if result.returncode != 0:
        return None, (result.stderr or result.stdout or "trivy failed").strip()[-400:]
    try:
        return json.loads(result.stdout), None
    except json.JSONDecodeError as error:
        return None, f"trivy output was not JSON: {error}"


def summarise_vulnerabilities(report):
    """Turn a Trivy report into per-severity counters and a compact list."""
    counts = {"critical": 0, "high": 0, "medium": 0, "low": 0, "unknown": 0}
    findings = []
    for section in report.get("Results") or []:
        for vulnerability in section.get("Vulnerabilities") or []:
            severity = (vulnerability.get("Severity") or "UNKNOWN").lower()
            counts[severity if severity in counts else "unknown"] += 1
            findings.append(
                {
                    "id": vulnerability.get("VulnerabilityID"),
                    "package": vulnerability.get("PkgName"),
                    "installed_version": vulnerability.get("InstalledVersion"),
                    "fixed_version": vulnerability.get("FixedVersion") or "",
                    "severity": severity,
                    "title": (vulnerability.get("Title") or "")[:200],
                    "target": section.get("Target"),
                }
            )
    counts["total"] = sum(
        counts[key] for key in ("critical", "high", "medium", "low", "unknown")
    )
    counts["fixable"] = sum(1 for finding in findings if finding["fixed_version"])
    findings.sort(key=lambda finding: (
        ["critical", "high", "medium", "low", "unknown"].index(finding["severity"]),
        finding["id"] or "",
    ))
    return counts, findings


def file_sha256(path):
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def enrich_image(image, usages, args, sbom_dir, cache_dir, checked_at):
    """Resolve, verify, generate SBOMs and scan a single image."""
    name, tag, pinned_digest = split_image(image)
    record = {
        "image": name,
        "reference": image,
        "tag": tag or "",
        "digest": pinned_digest or "",
        "platform_digest": pinned_digest or "",
        "index_digest": "",
        "platform": args.platform,
        "mutable_tag": bool(
            tag.lower() in MUTABLE_TAGS if tag else not pinned_digest
        ),
        "media_type": "",
        "multi_arch": False,
        "environments": sorted(usages["environments"]),
        "components": sorted({usage["component"] for usage in usages["usages"]}),
        "usages": sorted(
            usages["usages"],
            key=lambda usage: (
                usage["environment"],
                usage["namespace"],
                usage["workload"],
                usage["container"],
            ),
        ),
        "digest_resolution": "pinned" if pinned_digest else "resolved",
        "signature": {
            "status": "skipped",
            "method": "none",
            "identity": None,
            "issuer": None,
            "checked_at": checked_at,
            "detail": "",
        },
        "sbom": {},
        "cve": {"status": "skipped"},
    }

    if not pinned_digest and not args.skip_digests:
        try:
            resolution = resolve_digest(image, parse_platform(args.platform))
            record.update(
                digest=resolution["digest"],
                platform_digest=resolution["platform_digest"],
                index_digest=resolution["digest"] if resolution["index"] else "",
                media_type=resolution["media_type"],
                multi_arch=resolution["index"],
            )
            if resolution["index"] and not resolution.get("platform_found"):
                record["digest_resolution"] = "platform-missing"
        except (RuntimeError, json.JSONDecodeError, subprocess.TimeoutExpired) as error:
            record["digest_resolution"] = "error"
            record["error"] = str(error)[-300:]
            log(f"[digest] {image}: {record['error'].splitlines()[0]}")

    verify_digest = record["index_digest"] or record["digest"] or record["platform_digest"]

    if not args.skip_signatures:
        record["signature"] = verify_signature(
            name, verify_digest, args.public_key, checked_at
        )
        log(f"[signature] {image}: {record['signature']['status']}")

    if not args.skip_sbom:
        sboms = generate_sboms(
            name,
            record["platform_digest"],
            record["tag"],
            sbom_dir,
            args.sbom_formats,
        )
        record["sbom"] = sboms
        if any(entry.get("file") for entry in sboms.values()):
            log(f"[sbom] {image}: {', '.join(k for k, v in sboms.items() if v.get('file'))}")

    cdx_entry = record["sbom"].get("cyclonedx-json") or {}
    if not args.skip_scan and cdx_entry.get("file"):
        cdx_path = os.path.join(os.path.dirname(sbom_dir), cdx_entry["file"])
        report, error = trivy_scan(cdx_path, cache_dir)
        if report is None:
            record["cve"] = {"status": "error", "detail": error}
            log(f"[cve] {image}: error")
        else:
            counts, findings = summarise_vulnerabilities(report)
            record["cve"] = {"status": "scanned", **counts, "findings": findings}
            log(
                f"[cve] {image}: {counts['critical']}C {counts['high']}H "
                f"{counts['medium']}M {counts['low']}L"
            )

    return record


def containers_markdown(report):
    """Render the human-readable container table."""
    summary = report["summary"]
    title = report["release"] or "unreleased"
    lines = [
        f"# Containers in MijnBureau {title}",
        "",
        f"Generated at {report['generated_at']} from the rendered `{'` and `'.join(report['environments'])}` "
        f"manifests (platform `{report['platform']}`).",
        "",
        "Digests and SBOMs describe exactly what this release deploys. The signature "
        "column is report-only: most upstream images are not cosign-signed.",
        "",
        "## Summary",
        "",
        f"- Images: **{summary['images']}**",
        f"- Signed: **{summary['signed']}** (keyless {summary['signed_keyless']}, key {summary['signed_key']})",
        f"- Unsigned: **{summary['unsigned']}**",
        f"- Signed by an untrusted key: **{summary['unverifiable']}**",
        f"- Verification errors: **{summary['signature_errors']}**",
        f"- Mutable tags: **{summary['mutable_tags']}**",
        f"- Vulnerabilities: **{summary['vulnerabilities']['critical']} critical**, "
        f"**{summary['vulnerabilities']['high']} high**, "
        f"**{summary['vulnerabilities']['medium']} medium**, "
        f"**{summary['vulnerabilities']['low']} low**",
        "",
        "## Images",
        "",
        "| Component | Image | Tag | Digest | Environments | Signature | CVEs (C/H/M/L) | SBOM |",
        "|---|---|---|---|---|---|---|---|",
    ]
    for image in report["images"]:
        digest = image["digest"] or image["platform_digest"]
        short_digest = f"`{digest.split(':')[-1][:12]}`" if digest else "-"
        components = ", ".join(image["components"]) or image["image"].split("/")[-1]
        signature = image["signature"]
        if signature["status"] == "verified":
            signature_cell = f"verified ({signature['method']})"
        elif signature["status"] == "unsigned":
            signature_cell = "unsigned"
        elif signature["status"] == "unverifiable":
            signature_cell = "signed (unverifiable)"
        else:
            signature_cell = signature["status"]
        cve = image["cve"]
        if cve.get("status") == "scanned":
            cve_cell = f"{cve['critical']}/{cve['high']}/{cve['medium']}/{cve['low']}"
        else:
            cve_cell = cve.get("status", "n/a")
        sbom_cell = ", ".join(
            f"[{name.split('-')[0].upper()}]({entry['file']})"
            for name, entry in image["sbom"].items()
            if entry.get("file")
        ) or "-"
        tag = image["tag"] or "-"
        if image["mutable_tag"]:
            tag = f"{tag} (mutable)"
        lines.append(
            f"| {components} | `{image['image']}` | `{tag}` | {short_digest} | "
            f"{', '.join(image['environments'])} | {signature_cell} | {cve_cell} | {sbom_cell} |"
        )
    lines.extend(
        [
            "",
            "## Verification",
            "",
            "See the [supply chain documentation](https://minbzk.github.io/mijn-bureau-infra/docs/security/supply-chain) "
            "for the commands that verify this report.",
            "",
            "Signature status values:",
            "",
            "- `verified (keyless)`: a Sigstore keyless signature from a Fulcio certificate was found.",
            "- `verified (key)`: the release key in `cosign.pub` signed the image.",
            "- `unsigned`: no cosign signature was published for the image digest.",
            "- `signed (unverifiable)`: a signature exists, but not by a Fulcio certificate or `cosign.pub`, so it cannot be validated here.",
            "- `error`: the registry could not be queried, or verification failed.",
            "",
        ]
    )
    return "\n".join(lines)


def write_yaml(path, payload):
    with open(path, "w", encoding="utf-8") as handle:
        yaml.safe_dump(payload, handle, sort_keys=False, allow_unicode=True)


def write_json(path, payload):
    with open(path, "w", encoding="utf-8") as handle:
        json.dump(payload, handle, indent=2, sort_keys=False)
        handle.write("\n")


def write_sha256sums(directory):
    path = os.path.join(directory, "SHA256SUMS")
    entries = []
    for root, _dirs, files in os.walk(directory):
        for name in sorted(files):
            if name == "SHA256SUMS":
                continue
            target = os.path.join(root, name)
            entries.append(f"{file_sha256(target)}  {os.path.relpath(target, directory)}")
    with open(path, "w", encoding="utf-8") as handle:
        handle.write("\n".join(entries) + "\n")
    return path


def build_summary(images):
    vulnerabilities = {"critical": 0, "high": 0, "medium": 0, "low": 0, "unknown": 0, "total": 0}
    signed_keyless = 0
    signed_key = 0
    unsigned = 0
    unverifiable = 0
    signature_errors = 0
    for image in images:
        signature = image["signature"]
        if signature["status"] == "verified":
            if signature["method"] == "keyless":
                signed_keyless += 1
            else:
                signed_key += 1
        elif signature["status"] == "unsigned":
            unsigned += 1
        elif signature["status"] == "unverifiable":
            unverifiable += 1
        elif signature["status"] == "error":
            signature_errors += 1
        cve = image["cve"]
        if cve.get("status") == "scanned":
            for key in vulnerabilities:
                vulnerabilities[key] += cve.get(key, 0)
    return {
        "images": len(images),
        "signed": signed_keyless + signed_key,
        "signed_keyless": signed_keyless,
        "signed_key": signed_key,
        "unsigned": unsigned,
        "unverifiable": unverifiable,
        "signature_errors": signature_errors,
        "mutable_tags": sum(1 for image in images if image["mutable_tag"]),
        "vulnerabilities": vulnerabilities,
    }


def main():
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument(
        "--environment",
        action="append",
        dest="environments",
        help="Environment to render; repeat for several (default: demo and production).",
    )
    parser.add_argument("--output-dir", default="output/release", help="Report output directory.")
    parser.add_argument(
        "--render-dir",
        help="Directory for rendered manifests (default: <output-dir>/render).",
    )
    parser.add_argument(
        "--skip-render",
        action="store_true",
        help="Reuse an existing render directory instead of rendering again.",
    )
    parser.add_argument("--platform", default="linux/amd64", help="Target platform for digests and SBOMs.")
    parser.add_argument("--release-tag", default="", help="Release tag recorded in the report.")
    parser.add_argument(
        "--sbom-formats",
        default="cyclonedx-json,spdx-json",
        help="Comma separated Syft formats (default: cyclonedx-json,spdx-json).",
    )
    parser.add_argument("--public-key", default="cosign.pub", help="Public key for key-based verification.")
    parser.add_argument("--jobs", type=int, default=4, help="Images processed in parallel.")
    parser.add_argument(
        "--only",
        default="",
        help="Only process images whose reference matches this regular expression.",
    )
    parser.add_argument("--skip-digests", action="store_true")
    parser.add_argument("--skip-signatures", action="store_true")
    parser.add_argument("--skip-sbom", action="store_true")
    parser.add_argument("--skip-scan", action="store_true")
    parser.add_argument("--helmfile", default="helmfile", help="helmfile binary to use.")
    args = parser.parse_args()

    environments = args.environments or ["demo", "production"]
    args.sbom_formats = {
        name.strip(): {
            "cyclonedx-json": "cdx.json",
            "spdx-json": "spdx.json",
        }.get(name.strip(), f"{slugify(name.strip())}.json")
        for name in args.sbom_formats.split(",")
        if name.strip()
    }

    if not os.environ.get("MIJNBUREAU_MASTER_PASSWORD"):
        sys.exit("MIJNBUREAU_MASTER_PASSWORD must be set to render the manifests")

    reported_at = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    checked_at = reported_at.isoformat().replace("+00:00", "Z")

    output_dir = os.path.abspath(args.output_dir)
    security_dir = os.path.join(output_dir, "security")
    sbom_dir = os.path.join(security_dir, "sbom")
    cache_dir = os.path.join(output_dir, ".cache", "trivy")
    render_dir = os.path.abspath(args.render_dir or os.path.join(output_dir, "render"))
    os.makedirs(sbom_dir, exist_ok=True)
    os.makedirs(cache_dir, exist_ok=True)

    versions = tool_versions(
        {
            "skopeo": ["--version"],
            "cosign": ["version"],
            "syft": ["version"],
            "trivy": ["--version"],
            "helmfile": ["--version"],
        }
    )

    if args.skip_render:
        rendered = {
            environment: os.path.join(render_dir, environment)
            for environment in environments
            if os.path.isdir(os.path.join(render_dir, environment))
        }
        missing = [environment for environment in environments if environment not in rendered]
        if missing:
            sys.exit(f"no rendered manifests for {', '.join(missing)} in {render_dir}")
    else:
        rendered = render_manifests(environments, render_dir, args.helmfile)

    images = collect_images(rendered)
    if args.only:
        pattern = re.compile(args.only)
        images = {image: usage for image, usage in images.items() if pattern.search(image)}
    log(f"[collect] {len(images)} distinct images across {', '.join(rendered)}")

    if not images:
        sys.exit("no container images found in the rendered manifests")

    results = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=max(1, args.jobs)) as pool:
        futures = {
            pool.submit(
                enrich_image,
                image,
                usage,
                args,
                sbom_dir,
                cache_dir,
                checked_at,
            ): image
            for image, usage in images.items()
        }
        for future in concurrent.futures.as_completed(futures):
            image = futures[future]
            try:
                results.append(future.result())
            except Exception as error:  # noqa: BLE001 - report-only generation
                log(f"[error] {image}: {error}")
                name, tag, digest = split_image(image)
                results.append(
                    {
                        "image": name,
                        "reference": image,
                        "tag": tag or "",
                        "digest": digest or "",
                        "platform_digest": digest or "",
                        "index_digest": "",
                        "platform": args.platform,
                        "mutable_tag": False,
                        "media_type": "",
                        "multi_arch": False,
                        "environments": sorted(usage["environments"]),
                        "components": sorted({u["component"] for u in usage["usages"]}),
                        "usages": usage["usages"],
                        "digest_resolution": "error",
                        "error": str(error)[:400],
                        "signature": {
                            "status": "error",
                            "method": "none",
                            "identity": None,
                            "issuer": None,
                            "checked_at": checked_at,
                            "detail": str(error)[:300],
                        },
                        "sbom": {},
                        "cve": {"status": "error", "detail": str(error)[:300]},
                    }
                )

    results.sort(key=lambda record: record["reference"])

    source_commit = run(["git", "rev-parse", "HEAD"], check=False).stdout.strip() or None
    source_commit = source_commit.splitlines()[0] if source_commit else None

    # Findings live in cve.json; keep containers.json focused on the inventory
    # so the website can download it for every release.
    images_for_json = []
    for image in results:
        entry = dict(image)
        entry["cve"] = {
            key: value for key, value in image["cve"].items() if key != "findings"
        }
        images_for_json.append(entry)

    report = {
        "release": args.release_tag,
        "source_commit": source_commit,
        "generated_at": checked_at,
        "environments": list(rendered),
        "platform": args.platform,
        "tools": versions,
        "summary": build_summary(results),
        "images": images_for_json,
    }

    write_json(os.path.join(security_dir, "containers.json"), report)

    lock = {
        "release": args.release_tag,
        "generated_at": checked_at,
        "platform": args.platform,
        "images": [
            {
                "image": image["image"],
                "tag": image["tag"],
                "digest": image["digest"],
                "platform_digest": image["platform_digest"],
                "mutable_tag": image["mutable_tag"],
                "environments": image["environments"],
            }
            for image in results
        ],
    }
    write_yaml(os.path.join(security_dir, "images.lock.yaml"), lock)

    write_json(
        os.path.join(security_dir, "signatures.json"),
        {
            "generated_at": checked_at,
            "checked": len(results),
            "images": [
                {
                    "image": image["image"],
                    "digest": image["index_digest"] or image["digest"],
                    **image["signature"],
                }
                for image in results
            ],
        },
    )

    write_json(
        os.path.join(security_dir, "sbom-index.json"),
        {
            "generated_at": checked_at,
            "platform": args.platform,
            "sboms": [
                {
                    "image": image["image"],
                    "digest": image["platform_digest"],
                    **{
                        sbom_format: entry
                        for sbom_format, entry in image["sbom"].items()
                    },
                }
                for image in results
            ],
        },
    )

    write_json(
        os.path.join(security_dir, "cve.json"),
        {
            "generated_at": checked_at,
            "summary": report["summary"]["vulnerabilities"],
            "images": [
                {
                    "image": image["image"],
                    "digest": image["platform_digest"],
                    "status": image["cve"].get("status"),
                    "counts": {
                        key: image["cve"].get(key, 0)
                        for key in ("critical", "high", "medium", "low", "unknown", "total", "fixable")
                    },
                    "findings": image["cve"].get("findings", []),
                }
                for image in results
            ],
        },
    )

    with open(os.path.join(security_dir, "containers.md"), "w", encoding="utf-8") as handle:
        handle.write(containers_markdown(report))

    with open(os.path.join(security_dir, "README.md"), "w", encoding="utf-8") as handle:
        handle.write(
            "# Release security report\n\n"
            f"Generated at {checked_at} for `{args.release_tag or 'unreleased'}` from the rendered "
            f"`{'` and `'.join(rendered)}` manifests.\n\n"
            "| File | Contents |\n|---|---|\n"
            "| `containers.json` | Machine-readable inventory: images, digests, usages, signature status, SBOM and CVE summary. |\n"
            "| `containers.md` | Human-readable inventory table. |\n"
            "| `images.lock.yaml` | Tag to digest lock for this release. |\n"
            "| `signatures.json` | cosign verification result per image. |\n"
            "| `sbom/` | CycloneDX and SPDX SBOMs per image digest. |\n"
            "| `sbom-index.json` | SBOM file names with their SHA-256 checksums. |\n"
            "| `cve.json` | Trivy findings per image, from the CycloneDX SBOMs. |\n"
            "| `SHA256SUMS` | Checksums of every file in this directory. |\n\n"
            "Signature verification is report-only. Verify the report itself with "
            "`cosign verify-blob --key cosign.pub --bundle SHA256SUMS.sigstore.json SHA256SUMS`.\n"
        )

    write_sha256sums(security_dir)

    summary = report["summary"]
    log(
        "[done] "
        f"{summary['images']} images, {summary['signed']} signed, {summary['unsigned']} unsigned, "
        f"{summary['vulnerabilities']['critical']} critical / {summary['vulnerabilities']['high']} high CVEs"
    )
    print(os.path.join(security_dir, "containers.json"))


if __name__ == "__main__":
    main()
